{"prosrc":"
BEGIN
  -- If app sends user_id, force id to match it.
  IF NEW.user_id IS NOT NULL THEN
    NEW.id := NEW.user_id;
  END IF;

  -- If old code sends id but not user_id, copy id into user_id.
  IF NEW.user_id IS NULL AND NEW.id IS NOT NULL THEN
    NEW.user_id := NEW.id;
  END IF;

  RETURN NEW;
END;
","prokind":"f","proname":"sync_user_profiles_identity","full_definition":"CREATE OR REPLACE FUNCTION public.sync_user_profiles_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- If app sends user_id, force id to match it.
  IF NEW.user_id IS NOT NULL THEN
    NEW.id := NEW.user_id;
  END IF;

  -- If old code sends id but not user_id, copy id into user_id.
  IF NEW.user_id IS NULL AND NEW.id IS NOT NULL THEN
    NEW.user_id := NEW.id;
  END IF;

  RETURN NEW;
END;
$function$
"}

