BEGIN
  IF NEW.subject_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.subjects s
       WHERE s.id = NEW.subject_id
         AND s.user_id = NEW.user_id
     )
  THEN
    RAISE EXCEPTION 'Selected subject does not belong to the resource owner';
  END IF;

  RETURN NEW;
END;
","prokind":"f","proname":"validate_resource_subject_ownership","full_definition":"CREATE OR REPLACE FUNCTION public.validate_resource_subject_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.subject_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.subjects s
       WHERE s.id = NEW.subject_id
         AND s.user_id = NEW.user_id
     )
  THEN
    RAISE EXCEPTION 'Selected subject does not belong to the resource owner';
  END IF;

  RETURN NEW;
END;
$function$
"}
